def _build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_waves_result(
    streaks: tuple[dict[str, object], ...],
    regression_wave_baseline_splits: tuple[int, ...],
    regression_wave_min_active_regressions: int,
    regression_wave_regression_wave_limit: int,
) -> dict[str, object]:
    """Group forecast split positions where enough streaks stay active.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_waves`.
    The streaks are the complete, already-bounded ``streaks`` tuple
    of
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_streaks_result`
    in its final order and ``regression_wave_baseline_splits`` the
    validated requested positions. Each requested position counts
    the distinct identities whose kept streak covers it, listed in
    that streak order, and maximal runs of adjacent requested
    positions reaching
    ``regression_wave_min_active_regressions`` active identities
    form the waves -- unrequested integer positions do not break
    adjacency, while a requested position below the threshold ends
    the run. ``regression_wave_regression_wave_limit`` bounds the
    final wave count, raising :class:`ValueError` rather than
    truncating. Every wave and point dict is built fresh and shares
    no mutable object with the streak records.
    """
    position_of = {
        split: index
        for index, split in enumerate(regression_wave_baseline_splits)
    }
    coverage: list[list[object]] = [
        [] for _ in regression_wave_baseline_splits
    ]
    for streak in streaks:
        identity = streak["identity"]
        start = position_of[streak["start_baseline_cutoffs"]]
        end = position_of[streak["end_baseline_cutoffs"]]
        for index in range(start, end + 1):
            coverage[index].append(identity)

    waves: list[dict[str, object]] = []
    current: list[dict[str, object]] = []
    for index, split in enumerate(regression_wave_baseline_splits):
        identities: list[object] = []
        seen: set[object] = set()
        for identity in coverage[index]:
            if identity in seen:
                continue
            seen.add(identity)
            identities.append(identity)
        if len(identities) >= regression_wave_min_active_regressions:
            current.append(
                {
                    "baseline_cutoffs": split,
                    "active_count": len(identities),
                    "identities": tuple(
                        BranchStore._freeze_lifetime_value(identity)
                        for identity in identities
                    ),
                }
            )
            continue
        if current:
            waves.append(
                BranchStore._build_lifetime_churn_regression_wave(
                    current
                )
            )
            current = []
    if current:
        waves.append(
            BranchStore._build_lifetime_churn_regression_wave(current)
        )

    if len(waves) > regression_wave_regression_wave_limit:
        raise ValueError(
            f"lifetime churn drift wave prediction scorecard "
            f"regression wave forecast scorecard regression wave "
            f"limit exceeded: {len(waves)} waves, limit is "
            f"{regression_wave_regression_wave_limit}"
        )

    split_seen: set[object] = set()
    identity_seen: set[object] = set()
    totals = {
        "splits": 0,
        "identities": 0,
        "waves": 0,
        "points": 0,
        "peak_active": 0,
    }
    for wave in waves:
        totals["waves"] += 1
        for point in wave["points"]:
            split_seen.add(point["baseline_cutoffs"])
            totals["points"] += 1
            if point["active_count"] > totals["peak_active"]:
                totals["peak_active"] = point["active_count"]
            for identity in point["identities"]:
                identity_seen.add(identity)
    totals["splits"] = len(split_seen)
    totals["identities"] = len(identity_seen)
    return {"waves": tuple(waves), "totals": totals}

